package rt

import (
	"reflect"
	"runtime"
)

// UserDefined reports whether method name on v is written by the user rather
// than promoted from an embedded generated type. Promoted methods are
// compiler-generated wrappers, which report "<autogenerated>" as their file.
// Without this check a promoted public virtual (SizeHint) would dispatch to
// itself forever.
func UserDefined(v any, name string) bool {
	t := reflect.TypeOf(v)
	if t == nil {
		return false
	}
	types := []reflect.Type{t}
	if t.Kind() == reflect.Pointer {
		types = append(types, t.Elem())
	}
	for _, tt := range types {
		m, ok := tt.MethodByName(name)
		if !ok {
			continue
		}
		pc := m.Func.Pointer()
		f := runtime.FuncForPC(pc)
		if f == nil {
			continue
		}
		if file, _ := f.FileLine(pc); file != "<autogenerated>" {
			return true
		}
	}
	return false
}
